package org.marketreview.nativeapp;
import android.content.Context;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.channels.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

final class QuantResearchStore {
 private final AtomicFile file;
 interface Work<T>{T run()throws Exception;}
 QuantResearchStore(Context c,String name)throws Exception{QuantResearchModel.need(name.matches("[A-Za-z0-9._-]+")&&!name.equals(".")&&!name.equals(".."),"需明确独立研究文件名");file=new AtomicFile(new File(c.getFilesDir(),name));read();}
 File filePath(){return file.getBaseFile();}
 private <T>T locked(String suffix,Work<T>w)throws Exception{try(RandomAccessFile f=new RandomAccessFile(filePath()+suffix,"rw");FileChannel ch=f.getChannel()){FileLock lock;try{lock=ch.tryLock();}catch(OverlappingFileLockException e){throw new IllegalStateException("研究文件正在保存");}QuantResearchModel.need(lock!=null,"研究文件正在保存");try{return w.run();}finally{lock.release();}}}
 // Deep numeric equality matches QJsonValue equality without losing unknown nested fields.
 static boolean equal(Object a,Object b)throws Exception{if(a==JSONObject.NULL||b==JSONObject.NULL)return a==b;if(a instanceof Number&&b instanceof Number)return Double.compare(((Number)a).doubleValue(),((Number)b).doubleValue())==0;if(a instanceof JSONObject&&b instanceof JSONObject){JSONObject x=(JSONObject)a,y=(JSONObject)b;if(x.length()!=y.length())return false;for(Iterator<String>it=x.keys();it.hasNext();){String k=it.next();if(!y.has(k)||!equal(x.get(k),y.get(k)))return false;}return true;}if(a instanceof JSONArray&&b instanceof JSONArray){JSONArray x=(JSONArray)a,y=(JSONArray)b;if(x.length()!=y.length())return false;for(int i=0;i<x.length();i++)if(!equal(x.get(i),y.get(i)))return false;return true;}return Objects.equals(a,b);}
 static JSONObject empty()throws Exception{return QuantResearchModel.object("schema","quant-native-workspace/v1","revision",0,"records",new JSONArray());}
 static void validateRecord(JSONObject r)throws Exception{String kind=r.getString("kind");QuantResearchModel.need(!r.getString("id").isEmpty(),"研究记录没有ID");if(kind.equals("dataset")||kind.equals("archive")){JSONObject parsed=QuantResearchModel.importText(r.getString("rawUtf8"));QuantResearchModel.need(parsed.getString("id").equals(r.getString("id"))&&parsed.getString("kind").equals(kind)&&equal(parsed.get("original"),r.get("original")),"原始文件/摘要/记录不一致");}else{QuantResearchModel.need(kind.equals("run"),"未知研究记录类别");QuantResearchModel.need(Arrays.asList("queued","running","completed","failed","cancelled","interrupted").contains(r.getString("status")),"任务状态无效");QuantResearchModel.validateConfig(r.getJSONObject("config"));r.getString("datasetId");JSONArray materials=r.getJSONArray("materials");for(int i=0;i<materials.length();i++)PersonMethodModel.validateVersion(materials.getJSONObject(i));if(r.getString("status").equals("completed")){JSONObject result=r.getJSONObject("result");QuantResearchModel.need(result.getString("schema").equals("quant-native-result/v1")&&result.getString("engine").equals("native-controlled-strategy-baseline/v1")&&result.getString("status").equals("completed")&&result.getString("validationStatus").equals("exploratory")&&!result.getBoolean("automaticTrading")&&result.getString("dataSha256").equals(r.getString("datasetId"))&&equal(result.get("config"),r.get("config"))&&equal(result.get("materials"),r.get("materials"))&&result.getJSONArray("folds").length()>=3,"结果与冻结输入或探索性合同不一致");}}}
 static JSONObject validate(JSONObject o)throws Exception{QuantResearchModel.need(o.getString("schema").equals("quant-native-workspace/v1"),"研究文件损坏，未重建");QuantResearchModel.number(o,"revision",0,9007199254740991d,true);JSONArray rows=o.getJSONArray("records");Set<String>ids=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);validateRecord(r);QuantResearchModel.need(ids.add(r.getString("id")),"重复记录ID");}return o;}
 private JSONObject readUnlocked()throws Exception{if(!filePath().exists()&&!new File(filePath()+".bak").exists())return empty();QuantResearchModel.need(filePath().length()<=32*1024*1024,"研究文件超过32MiB，未重建");byte[]b=file.readFully();QuantResearchModel.need(b.length<=32*1024*1024,"研究文件超过32MiB，未重建");return validate(QuantResearchJson.parse(new String(b,StandardCharsets.UTF_8)));}
 private void write(JSONObject o)throws Exception{validate(o);byte[]b=o.toString().getBytes(StandardCharsets.UTF_8);QuantResearchModel.need(b.length<=32*1024*1024,"研究文件超过32MiB；未截断或覆盖");FileOutputStream out=null;try{out=file.startWrite();out.write(b);file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);throw e;}}
 JSONObject read()throws Exception{return locked(".lock",this::readUnlocked);}
 JSONObject get(String id)throws Exception{JSONArray a=read().getJSONArray("records");for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getString("id").equals(id))return a.getJSONObject(i);throw new IllegalArgumentException("研究记录不存在");}
 JSONObject put(JSONObject r,JSONObject expected)throws Exception{validateRecord(r);return locked(".lock",()->{JSONObject o=readUnlocked();JSONArray rows=o.getJSONArray("records");int index=-1;for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).getString("id").equals(r.getString("id")))index=i;JSONObject current=index<0?new JSONObject():rows.getJSONObject(index);QuantResearchModel.need(equal(current,expected),"研究记录已更改，请显式重读");if(current.length()>0)QuantResearchModel.need(current.getString("kind").equals("run")&&r.getString("kind").equals("run")&&current.getString("datasetId").equals(r.getString("datasetId"))&&equal(current.get("config"),r.get("config"))&&equal(current.get("materials"),r.get("materials")),"冻结研究输入不可修改");if(index<0)rows.put(r);else rows.put(index,r);o.put("revision",o.getLong("revision")+1);write(o);return new JSONObject(r.toString());});}
 JSONObject merge(JSONObject preview,JSONObject expected)throws Exception{return locked(".lock",()->{JSONObject o=readUnlocked();QuantResearchModel.need(equal(o,expected),"预览后研究库已变更，请重做预览");JSONArray rows=o.getJSONArray("records"),incoming=preview.getString("kind").equals("backup")?validate(preview.getJSONObject("original")).getJSONArray("records"):new JSONArray().put(preview);for(int i=0;i<incoming.length();i++){JSONObject r=incoming.getJSONObject(i);validateRecord(r);boolean exists=false;for(int j=0;j<rows.length();j++)if(rows.getJSONObject(j).getString("id").equals(r.getString("id"))){QuantResearchModel.need(equal(rows.getJSONObject(j),r),"同ID记录内容不一致，未覆盖");exists=true;}if(!exists)rows.put(r);}o.put("revision",o.getLong("revision")+1);write(o);return o;});}
 String exportText()throws Exception{return read().toString();}
 JSONObject loadView()throws Exception{return locked(".view.lock",()->{AtomicFile view=new AtomicFile(new File(filePath()+".view"));if(!view.getBaseFile().exists()&&!new File(filePath()+".view.bak").exists())return new JSONObject();byte[]b=view.readFully();QuantResearchModel.need(b.length<=32*1024*1024,"草稿超过32MiB");JSONObject o=QuantResearchJson.parse(new String(b,StandardCharsets.UTF_8));QuantResearchModel.need(o.getString("schema").equals("quant-native-view/v1"),"草稿损坏，未重建");return o;});}
 void saveView(JSONObject o,JSONObject expected)throws Exception{QuantResearchModel.need(o.getString("schema").equals("quant-native-view/v1"),"草稿格式无效");locked(".view.lock",()->{AtomicFile view=new AtomicFile(new File(filePath()+".view"));JSONObject current=new JSONObject();if(view.getBaseFile().exists()||new File(filePath()+".view.bak").exists())current=QuantResearchJson.parse(new String(view.readFully(),StandardCharsets.UTF_8));QuantResearchModel.need(equal(current,expected),"草稿已在另一页面修改，请显式重读");FileOutputStream out=null;try{out=view.startWrite();byte[]bytes=o.toString().getBytes(StandardCharsets.UTF_8);QuantResearchModel.need(bytes.length<=32*1024*1024,"草稿/预览超过32MiB，未截断");out.write(bytes);view.finishWrite(out);}catch(Exception e){if(out!=null)view.failWrite(out);throw e;}return null;});}
}
